class Solution {
public:
    std::vector<std::vector<std::string>> mostPopularCreator(std::vector<std::string>& creators, std::vector<std::string>& ids, std::vector<int>& views) {
        std::unordered_map<std::string, long long> total_views;
        std::unordered_map<std::string, std::pair<int, std::string>> best_video;
        for (size_t i = 0; i < creators.size(); ++i) {
            const auto& c = creators[i];
            const auto& vid = ids[i];
            int v = views[i];
            total_views[c] += v;
            if (best_video.find(c) == best_video.end()) {
                best_video[c] = {v, vid};
            } else {
                int cv = best_video[c].first;
                const auto& cvid = best_video[c].second;
                if (v > cv || (v == cv && vid < cvid)) {
                    best_video[c] = {v, vid};
                }
            }
        }
        long long max_views = -1;
        for (const auto& pair : total_views) {
            if (pair.second > max_views) max_views = pair.second;
        }
        std::vector<std::vector<std::string>> ans;
        for (const auto& pair : total_views) {
            if (pair.second == max_views) {
                ans.push_back({pair.first, best_video[pair.first].second});
            }
        }
        return ans;
    }
};

class Solution {
    public java.util.List<java.util.List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        java.util.Map<String, Long> totalViews = new java.util.HashMap<>();
        java.util.Map<String, int[]> bestViews = new java.util.HashMap<>();
        java.util.Map<String, String> bestIds = new java.util.HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            String c = creators[i];
            String vid = ids[i];
            int v = views[i];
            totalViews.put(c, totalViews.getOrDefault(c, 0L) + v);
            if (!bestViews.containsKey(c)) {
                bestViews.put(c, new int[]{v});
                bestIds.put(c, vid);
            } else {
                int cv = bestViews.get(c)[0];
                String cvid = bestIds.get(c);
                if (v > cv || (v == cv && vid.compareTo(cvid) < 0)) {
                    bestViews.get(c)[0] = v;
                    bestIds.put(c, vid);
                }
            }
        }
        long maxViews = -1;
        for (long tot : totalViews.values()) {
            if (tot > maxViews) maxViews = tot;
        }
        java.util.List<java.util.List<String>> ans = new java.util.ArrayList<>();
        for (java.util.Map.Entry<String, Long> entry : totalViews.entrySet()) {
            if (entry.getValue() == maxViews) {
                ans.add(java.util.Arrays.asList(entry.getKey(), bestIds.get(entry.getKey())));
            }
        }
        return ans;
    }
}

var mostPopularCreator = function(creators, ids, views) {
    const totalViews = new Map();
    const bestVideo = new Map();
    for (let i = 0; i < creators.length; i++) {
        const c = creators[i];
        const vid = ids[i];
        const v = views[i];
        totalViews.set(c, (totalViews.get(c) || 0) + v);
        if (!bestVideo.has(c)) {
            bestVideo.set(c, { v, vid });
        } else {
            const cur = bestVideo.get(c);
            if (v > cur.v || (v === cur.v && vid < cur.vid)) {
                bestVideo.set(c, { v, vid });
            }
        }
    }
    let maxViews = -1;
    for (const tot of totalViews.values()) {
        if (tot > maxViews) maxViews = tot;
    }
    const ans = [];
    for (const [c, tot] of totalViews.entries()) {
        if (tot === maxViews) {
            ans.push([c, bestVideo.get(c).vid]);
        }
    }
    return ans;
};
